const questions = [
  {
    id: 'q1',
    question: 'Which of the following are compiled languages?',
    helpText: 'Compiled languages are translated into machine code before execution.',
    options: [
      { id: 'q1-o1', label: 'C++' },
      { id: 'q1-o2', label: 'Rust' },
      { id: 'q1-o3', label: 'JavaScript' },
      { id: 'q1-o4', label: 'Go' }
    ],
    correct: ['q1-o1', 'q1-o2', 'q1-o4']
  },
  {
    id: 'q2',
    question: 'Which languages are commonly used for systems programming?',
    options: [
      { id: 'q2-o1', label: 'C' },
      { id: 'q2-o2', label: 'PHP' },
      { id: 'q2-o3', label: 'Assembly' },
      { id: 'q2-o4', label: 'Ruby' }
    ],
    correct: ['q2-o1', 'q2-o3']
  },
  {
    id: 'q3',
    question: 'Which of these languages support functional programming paradigms?',
    options: [
      { id: 'q3-o1', label: 'Haskell' },
      { id: 'q3-o2', label: 'Lisp' },
      { id: 'q3-o3', label: 'Scala' },
      { id: 'q3-o4', label: 'Fortran 77' }
    ],
    correct: ['q3-o1', 'q3-o2', 'q3-o3']
  }
];

function Quiz() {
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (questionId, optionId) => {
    setSelected(prev => {
      const current = prev[questionId] || [];
      if (current.includes(optionId)) {
        return { ...prev, [questionId]: current.filter(id => id !== optionId) };
      } else {
        return { ...prev, [questionId]: [...current, optionId] };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  const calculateScore = () => {
    let score = 0;
    questions.forEach(q => {
      const userAnswers = selected[q.id] || [];
      const isCorrect = 
        userAnswers.length === q.correct.length && 
        userAnswers.every(val => q.correct.includes(val));
      if (isCorrect) score++;
    });
    return score;
  };

  return (
    <div className="quiz-container">
      <h1>Computer Language Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map((q, index) => (
          <div key={q.id} className="form-field">
            <fieldset aria-describedby={q.helpText ? `${q.id}-help` : undefined}>
              <legend>{index + 1}. {q.question}</legend>
              {q.helpText && (
                <p id={`${q.id}-help`} className="help-text">
                  {q.helpText}
                </p>
              )}
              <div className="options-group">
                {q.options.map(opt => (
                  <label key={opt.id} className="option">
                    <input
                      type="checkbox"
                      checked={(selected[q.id] || []).includes(opt.id)}
                      onChange={() => handleToggle(q.id, opt.id)}
                      disabled={submitted}
                    />
                    {opt.label}
                  </label>
                ))}
              </div>
            </fieldset>
          </div>
        ))}
        {!submitted && <button type="submit">Submit Answers</button>}
      </form>
      {submitted && (
        <div className="results" role="alert">
          <h2>Your Score: {calculateScore()} / {questions.length}</h2>
          <button onClick={() => { setSubmitted(false); setSelected({}); }}>Restart Quiz</button>
        </div>
      )}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
